export function languageName(entry: ElyraLanguageCatalogEntry, uiLocale: string): string {
  const base = uiLocale.toLowerCase().split(/[-_]/)[0];
  return entry.names[base] ?? entry.names.en ?? entry.names.zh ?? entry.code;
}
